-- Spoken languages and proficiency

create table "public"."languages" (
  "id" bigint primary key generated by default as identity,
  "name" varchar,
  "proficiency" varchar,
  "description" varchar,
  "user" uuid,
  "order" smallint,
  "is_active" boolean not null default true
);

alter table "public"."languages" add constraint "languages_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."languages" enable row level security;
create policy "Enable read access for all users" on "public"."languages" for select using (true);

grant all on "public"."languages" to postgres, anon, authenticated, service_role;
